// Recibe TODO lo que le llega a signal-api (tus chats, confirmaciones de lectura, etc.).
// Solo deja pasar comandos que tú escribiste en tu "Nota personal", o que llegan
// de un número en AUTORIZADOS. Este flujo no guarda ejecuciones, para no almacenar
// tus mensajes privados.
const AUTORIZADOS = [];   // ej. ['+5216141234567'] para aceptar comandos de otro número
const COMANDOS = ['estado', 'revisar', 'pausar', 'reanudar', 'ayuda'];

const salida = [];
for (const item of $input.all()) {
  try {
    const p = item.json.body ?? item.json;
    const env = p.envelope ?? p.params?.envelope;
    const cuenta = p.account ?? p.params?.account;
    if (!env || !cuenta) continue;

    const desde = env.sourceNumber ?? env.source;
    const enviado = env.syncMessage?.sentMessage;
    let texto = null;
    let responderA = null;

    if (enviado && desde === cuenta &&
        ((enviado.destinationNumber ?? enviado.destination) === cuenta ||
         (enviado.destinationUuid && enviado.destinationUuid === env.sourceUuid))) {
      texto = enviado.message;          // escrito por ti en "Nota personal"
      responderA = cuenta;
    } else if (env.dataMessage && AUTORIZADOS.includes(desde)) {
      texto = env.dataMessage.message;
      responderA = desde;
    }
    if (typeof texto !== 'string') continue;

    const comando = texto.trim().toLowerCase().replace(/^[\/!]/, '');
    if (COMANDOS.includes(comando)) salida.push({ json: { comando, responderA } });
  } catch (e) {
    // Mensaje con formato inesperado: se ignora
  }
}
return salida;
